  for(const face of faces){const vertices=[];for(let i=1;i<face.length-1;i++)for(const p of[face[0],face[i],face[i+1]])vertices.push(p[0],p[2],p[1]);const geo=new THREE.BufferGeometry();geo.setAttribute('position',new THREE.Float32BufferAttribute(vertices,3));geo.computeVertexNormals();const mesh=new THREE.Mesh(geo,materials.roof);mesh.castShadow=true;mesh.receiveShadow=true;parent.add(mesh);}
